public final class CommunityActivity extends HubActivity {
 private JSONArray mergeRecommendations(JSONObject prior,JSONArray incoming)throws Exception{return CommunityPackage.mergeRecommendations(prior==null?null:prior.optJSONArray("items"),incoming);}
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private CheckBox includeLibrary;private TextView shareStatus,feedStatus;private LinearLayout feed;private EditText endpoint,feedEndpoint;private LocalShareServer server;private boolean dead;private String exportValue="";
 @Override public void onCreate(Bundle s){super.onCreate(s);LinearLayout body=page(tx("المشاركة والمجتمع","Sharing & community"),tx("ملفاتك وإعداداتك • مشاركة فعلية مع من تختاره","Your files and settings • real exchange with people you choose"));LinearLayout c=card(body);c.addView(text(tx("حزمة إعدادات IRAQhub","IRAQhub settings package"),21,true));note(c,tx("شارك تنسيق الشاشة ومزامنة الترجمة. لا تتضمن الحزمة رمز الرقابة الأبوية أو تفعيل الطبقات أو بيانات حسابات. يمكنك إضافة مكتبة القنوات اختيارياً.","Share screen layout and subtitle timing. Packages exclude parental PINs, layer activation and account data. Your channel library can optionally be included."));includeLibrary=check(c,tx("تضمين مكتبة IPTV ودليل البرامج — قد تحتوي روابط اشتراك خاصة","Include IPTV library and EPG — may contain private subscription URLs"),false);action(c,tx("تصدير حزمة إلى ملف","Export package to file"),()->previewExport(false));action(c,tx("مشاركة قريبة عبر الشبكة المحلية","Share with a nearby device over LAN"),()->previewExport(true));action(c,tx("إيقاف المشاركة المحلية","Stop LAN sharing"),this::stopSharing);shareStatus=text(tx("المشاركة المحلية متوقفة","LAN sharing is off"),16,false);shareStatus.setTextColor(ACCENT);c.addView(shareStatus);note(c,tx("المشاركة القريبة تعمل أثناء بقاء هذه الصفحة مفتوحة. الرابط العشوائي يمنح الوصول للحزمة المختارة؛ أرسله لمن تختاره فقط.","Nearby sharing works while this page remains open. Its random link grants access to the approved package; give it only to your intended recipient."));LinearLayout incoming=card(body);incoming.addView(text(tx("استقبال حزمة","Receive a package"),21,true));action(incoming,tx("استيراد ملف IRAQhub","Import IRAQhub file"),()->openDocument(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),21));endpoint=field(incoming,tx("رابط حزمة HTTPS أو رابط جهاز محلي","Package HTTPS URL or nearby device URL"),"");action(incoming,tx("جلب ومعاينة الحزمة","Fetch and preview package"),()->fetchPackage(endpoint.getText().toString().trim()));action(incoming,tx("مشاركة ملف من الجهاز: ترجمة، شعار، خط، صوت…","Share a device file: subtitles, badge, font, audio…"),()->openDocument(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),23));LinearLayout community=card(body);community.addView(text(tx("ترشيحات المجتمع","Community recommendations"),21,true));note(community,tx("أضف رابط خلاصة JSON يديرها مجتمعك. لا توجد حسابات أو منشورات مشتركة قبل ربط مصدر فعلي. تستطيع حفظ ومشاركة الترشيحات محلياً.","Connect a JSON feed maintained by your community. No accounts or shared posts are shown before a real source is connected. Recommendations can be saved and shared locally."));feedEndpoint=field(community,tx("رابط خلاصة المجتمع HTTPS","Community feed HTTPS URL"),prefs().getString("community_feed",""));action(community,tx("تحديث الترشيحات","Refresh recommendations"),this::fetchFeed);action(community,tx("إضافة ترشيح محلي","Add local recommendation"),this::addRecommendation);feedStatus=text("",14,false);community.addView(feedStatus);feed=col();community.addView(feed);renderFeed(HubFiles.read(this,"recommendations.json"));}
 private JSONObject makePackage()throws Exception{JSONObject all=new JSONObject();for(Map.Entry<String,?>e:prefs().getAll().entrySet())all.put(e.getKey(),e.getValue());JSONObject result=new JSONObject().put("format","SmartHubPlusShare").put("version",1).put("createdAt",System.currentTimeMillis()).put("subtitle_timings",SubtitleSyncRepository.exportSaved(this)).put("settings",CommunityPackage.safeSettings(all));if(includeLibrary.isChecked())result.put("library",new JSONObject(new PlaylistRepository(this).exportJson()));JSONObject rec=HubFiles.read(this,"recommendations.json");if(rec!=null)result.put("recommendations",rec.optJSONArray("items"));return result;}
 private void openDocument(Intent request,int code){try{launchDocument(request,code);}catch(android.content.ActivityNotFoundException error){toast(tx("لا يوجد منتقي ملفات على الجهاز. استخدم المشاركة عبر الشبكة المحلية أو ثبّت منتقي ملفات متوافقاً.","No document picker is installed. Use LAN sharing or install a compatible document picker."));}}
 private void previewExport(boolean lan){try{JSONObject pack=makePackage();String value=pack.toString(2);int count=pack.optJSONObject("library")==null?0:pack.getJSONObject("library").getJSONArray("channels").length();new AlertDialog.Builder(this).setTitle(tx("معاينة المشاركة","Share preview")).setMessage(tx("إعدادات مسموحة: ","Approved settings: ")+pack.getJSONObject("settings").length()+tx("\nقنوات مضمّنة: ","\nIncluded channels: ")+count+tx("\nلا يشارك التطبيق أي ملف آخر من الجهاز.","\nNo other device files are exposed." )).setPositiveButton(tx("متابعة","Continue"),(d,w)->{if(lan)startLan(value);else{exportValue=value;try{HubFiles.save(this,"pending_share.json",new JSONObject(value));}catch(Exception failure){toast(failure.getMessage());return;}openDocument(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").putExtra(Intent.EXTRA_TITLE,"SmartHubPlus-share.json").addCategory(Intent.CATEGORY_OPENABLE),22);}}).setNegativeButton(tx("إلغاء","Cancel"),null).show();}catch(Exception e){toast(e.getMessage());}}
 private void startLan(String value){stopSharing();try{server=new LocalShareServer(value.getBytes(StandardCharsets.UTF_8));String address=server.address();if(address.isEmpty()){stopSharing();toast(tx("لا يتوفر عنوان شبكة محلية","No LAN address is available"));return;}shareStatus.setText(address);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}catch(Exception e){toast(e.getMessage());}}
 private void stopSharing(){if(server!=null){server.close();server=null;}getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(shareStatus!=null)shareStatus.setText(tx("المشاركة المحلية متوقفة","LAN sharing is off"));}
 private void fetchPackage(String address){shareStatus.setText(tx("جارٍ جلب الحزمة…","Fetching package…"));worker.execute(()->{try{String value=download(address);JSONObject pack=CommunityPackage.validate(value);runOnUiThread(()->{if(!dead)previewImport(pack);});}catch(Exception e){runOnUiThread(()->{if(!dead)shareStatus.setText(tx("تعذر الاستقبال: ","Import failed: ")+e.getMessage());});}});}
 private void previewImport(JSONObject pack){try{int settings=pack.getJSONObject("settings").length();int timings=pack.optJSONArray("subtitle_timings")==null?0:pack.optJSONArray("subtitle_timings").length();JSONObject library=pack.optJSONObject("library");int channels=library==null?0:library.optJSONArray("channels")==null?0:library.getJSONArray("channels").length();new AlertDialog.Builder(this).setTitle(tx("تطبيق الحزمة؟","Apply this package?" )).setMessage(tx("إعدادات التنسيق: ","Layout settings: ")+settings+tx("\nتوقيتات ترجمة ستُحفظ: ","\nSubtitle timings to save: ")+timings+tx("\nقنوات ستُدمج: ","\nChannels to merge: ")+channels+tx("\nتظل طبقات الشاشة متوقفة حتى تشغّلها بنفسك.","\nScreen layers remain inactive until you enable them." )).setPositiveButton(tx("تطبيق","Apply"),(d,w)->worker.execute(()->{try{JSONObject safe=pack.getJSONObject("settings");SharedPreferences.Editor edit=prefs().edit();Iterator<String>keys=safe.keys();while(keys.hasNext()){String k=keys.next();Object v=safe.get(k);if("subtitle_offset".equals(k))edit.putLong(k,((Number)v).longValue());else if(v instanceof Boolean)edit.putBoolean(k,(Boolean)v);else if(v instanceof Integer)edit.putInt(k,(Integer)v);else if(v instanceof Number)edit.putLong(k,((Number)v).longValue());else edit.putString(k,(String)v);}edit.apply();SubtitleSyncRepository.importSaved(this,pack.optJSONArray("subtitle_timings"));if(library!=null)new PlaylistRepository(this).importJson(library.toString());JSONArray rec=pack.optJSONArray("recommendations");if(rec!=null)HubFiles.save(this,"recommendations.json",new JSONObject().put("items",mergeRecommendations(HubFiles.read(this,"recommendations.json"),safeRecommendations(rec))).put("savedAt",System.currentTimeMillis()));runOnUiThread(()->{if(!dead){shareStatus.setText(tx("تم استيراد الحزمة","Package imported"));renderFeed(HubFiles.read(this,"recommendations.json"));}});}catch(Exception e){runOnUiThread(()->{if(!dead)toast(e.getMessage());});}})).setNegativeButton(tx("إلغاء","Cancel"),null).show();}catch(Exception e){toast(e.getMessage());}}
 private void fetchFeed(){String url=feedEndpoint.getText().toString().trim();if(!url.startsWith("https://")){toast(tx("أدخل رابط HTTPS لخلاصة حقيقية","Enter an HTTPS URL for a real feed"));return;}prefs().edit().putString("community_feed",url).apply();feedStatus.setText(tx("جارٍ التحديث…","Refreshing…"));worker.execute(()->{try{JSONObject response=new JSONObject(HubHttp.get(url));if(!(response.opt("items") instanceof JSONArray))throw new IOException("Feed must contain an items array");JSONArray items=mergeRecommendations(HubFiles.read(this,"recommendations.json"),safeRecommendations(response.optJSONArray("items")));JSONObject saved=new JSONObject().put("items",items).put("savedAt",System.currentTimeMillis()).put("source",url);HubFiles.save(this,"recommendations.json",saved);runOnUiThread(()->{if(!dead)renderFeed(saved);});}catch(Exception e){runOnUiThread(()->{if(!dead)feedStatus.setText(tx("فشل التحديث؛ الترشيحات المحفوظة باقية: ","Refresh failed; saved recommendations retained: ")+e.getMessage());});}});}
 private JSONArray safeRecommendations(JSONArray data)throws Exception{JSONArray out=new JSONArray();if(data==null)return out;for(int j=0;j<Math.min(200,data.length());j++){JSONObject item=data.optJSONObject(j);if(item==null)continue;String title=item.optString("title").trim(),url=item.optString("url").trim(),note=item.optString("notes");if(title.isEmpty()||title.length()>300||note.length()>3000)continue;if(!url.isEmpty()&&!url.startsWith("https://"))continue;out.put(new JSONObject().put("title",title).put("url",url).put("notes",note));}return out;}
 private void renderFeed(JSONObject saved){feed.removeAllViews();JSONArray items=saved==null?null:saved.optJSONArray("items");if(items==null||items.length()==0){feedStatus.setText(tx("لا توجد ترشيحات محفوظة بعد","No saved recommendations yet"));return;}feedStatus.setText(tx("ترشيحات محفوظة: ","Saved recommendations: ")+items.length());for(int j=0;j<items.length();j++){JSONObject item=items.optJSONObject(j);if(item==null)continue;LinearLayout c=card(feed);c.addView(text(item.optString("title"),18,true));note(c,item.optString("notes"));String url=item.optString("url");if(url.startsWith("https://"))action(c,tx("فتح الرابط","Open link"),()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast(tx("لا يوجد متصفح","No browser installed"));}});}}
 private void addRecommendation(){LinearLayout form=col();form.setPadding(dp(18),dp(8),dp(18),dp(8));EditText title=field(form,tx("عنوان الترشيح","Recommendation title"),""),url=field(form,tx("رابط HTTPS اختياري","Optional HTTPS URL"),""),description=field(form,tx("ملاحظتك","Your notes"),"");new AlertDialog.Builder(this).setTitle(tx("ترشيح محلي","Local recommendation")).setView(form).setPositiveButton(tx("حفظ","Save"),(d,w)->{try{JSONObject old=HubFiles.read(this,"recommendations.json");JSONArray items=old==null?new JSONArray():old.optJSONArray("items");if(items==null)items=new JSONArray();items.put(new JSONObject().put("title",title.getText().toString()).put("url",url.getText().toString()).put("notes",description.getText().toString()));JSONObject saved=new JSONObject().put("items",safeRecommendations(items)).put("savedAt",System.currentTimeMillis());HubFiles.save(this,"recommendations.json",saved);renderFeed(saved);}catch(Exception e){toast(e.getMessage());}}).setNegativeButton(tx("إلغاء","Cancel"),null).show();}
 private static String download(String address)throws Exception{URL url=new URL(address);boolean https="https".equals(url.getProtocol()),lan="http".equals(url.getProtocol())&&InetAddress.getByName(url.getHost()).isSiteLocalAddress();if(!https&&!lan)throw new IOException("Use HTTPS or a local-network HTTP address");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(7000);c.setReadTimeout(12000);try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream()){return read(in,12*1024*1024);}}finally{c.disconnect();}}
 private static String read(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("File too large");out.write(b,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();worker.execute(()->{try{if(request==21){String value;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Cannot open file");value=read(in,12*1024*1024);}JSONObject pack=CommunityPackage.validate(value);runOnUiThread(()->{if(!dead)previewImport(pack);});}else if(request==22){JSONObject pending=HubFiles.read(this,"pending_share.json");if(pending==null)throw new IOException("Export data unavailable; begin export again");exportValue=pending.toString(2);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Cannot write file");out.write(exportValue.getBytes(StandardCharsets.UTF_8));}runOnUiThread(()->toast(tx("تم التصدير","Exported")));}else if(request==23){File folder=new File(getFilesDir(),"shared");folder.mkdirs();String name="shared-"+System.currentTimeMillis();try(android.database.Cursor info=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(info!=null&&info.moveToFirst())name=info.getString(0).replaceAll("[^A-Za-z0-9._-]","_");}if(name.isEmpty()||name.equals(".")||name.equals(".."))name="shared-file";File target=new File(folder,java.util.UUID.randomUUID().toString()+"-"+name);try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(target)){if(in==null)throw new IOException("Cannot open file");byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){if((total+=n)>16*1024*1024)throw new IOException("File exceeds 16 MB");out.write(b,0,n);}}Uri share=FileProvider.getUriForFile(this,getPackageName()+".files",target);String mime=getContentResolver().getType(uri);Intent send=new Intent(Intent.ACTION_SEND).setType(mime==null?"application/octet-stream":mime).putExtra(Intent.EXTRA_STREAM,share).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("IRAQhub file",share));runOnUiThread(()->{if(!dead)startActivity(Intent.createChooser(send,tx("مشاركة الملف","Share file")));});}}catch(Exception e){runOnUiThread(()->{if(!dead)toast(e.getMessage());});}});}
 @Override protected void onStop(){stopSharing();super.onStop();}@Override protected void onDestroy(){dead=true;stopSharing();worker.shutdownNow();super.onDestroy();}
}
